#!/bin/bash
# Run all PTM3D simulations for ALMA comparison
# Generated by setup_ptm3d_runs.py

PTM_BIN="/Users/paha3326/Library/CloudStorage/OneDrive-UCB-O365/europa/heat3d/ptm/build/bin/ptm_thermal_sim"
CONFIG_DIR="/Users/paha3326/Library/CloudStorage/OneDrive-UCB-O365/europa/heat3d/ptm/configs/alma"

# Check that PTM3D binary exists
if [ ! -f "$PTM_BIN" ]; then
    echo "ERROR: PTM3D binary not found at $PTM_BIN"
    echo "Build with: cd build && cmake --build . --target ptm_thermal_sim -j4"
    exit 1
fi

DEPTHS_FILE="$CONFIG_DIR/alma_depths.txt"

echo "\n============================================================"
echo "Running T1: Trumbo et al. (2018), Band 6, anti-Jovian"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_T1.yaml --locations $CONFIG_DIR/alma_T1_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running T2: Trumbo et al. (2018), Band 6, leading"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_T2.yaml --locations $CONFIG_DIR/alma_T2_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running T3: Trumbo et al. (2018), Band 6, sub-Jovian"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_T3.yaml --locations $CONFIG_DIR/alma_T3_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running T4: Trumbo et al. (2018), Band 6, trailing"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_T4.yaml --locations $CONFIG_DIR/alma_T4_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H1: Thelen et al. (2024), Band 7, trailing"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H1.yaml --locations $CONFIG_DIR/alma_H1_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H2: Thelen et al. (2024), Band 7, leading"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H2.yaml --locations $CONFIG_DIR/alma_H2_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H3: Thelen et al. (2024), Band 6, trailing"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H3.yaml --locations $CONFIG_DIR/alma_H3_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H4: Thelen et al. (2024), Band 6, trailing"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H4.yaml --locations $CONFIG_DIR/alma_H4_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H5: Thelen et al. (2024), Band 6, leading"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H5.yaml --locations $CONFIG_DIR/alma_H5_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H6: Thelen et al. (2024), Band 6, trailing"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H6.yaml --locations $CONFIG_DIR/alma_H6_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H7: Thelen et al. (2024), Band 3, leading"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H7.yaml --locations $CONFIG_DIR/alma_H7_locations.csv --depths $DEPTHS_FILE

echo "\n============================================================"
echo "Running H8: Thelen et al. (2024), Band 3, trailing"
echo "============================================================"
$PTM_BIN --config $CONFIG_DIR/alma_H8.yaml --locations $CONFIG_DIR/alma_H8_locations.csv --depths $DEPTHS_FILE

